from src.nodes.base import BaseNode
from src.runtime.lookdev import get_material_recommendation_engine
import json

class Hou_Mcp_Material_Recommend(BaseNode):
    name = "hou_mcp_material_recommend"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("asset_json", "string", widget_type="text", default="")
        self.add_input("renderer",   "string", widget_type="text", default="usd_preview_surface")
        # [AUTO-GENERATED-PORTS-END]
        self.add_output("recommendation_json", "string")
        self.add_output("material_name",        "string")
        self.add_output("confidence",           "float")

    async def execute(self, inputs):
        asset_json = str(inputs.get("asset_json", "") or "")
        renderer   = str(inputs.get("renderer",   "usd_preview_surface") or "usd_preview_surface")
        try:
            asset_dict = json.loads(asset_json) if asset_json.strip() else {}
        except Exception as exc:
            self.log_error(f"Failed to parse asset_json: {exc}")
            return {"recommendation_json": "{}", "material_name": "", "confidence": 0.0, "exec_out": True}
        try:
            engine = get_material_recommendation_engine()
            result = engine.recommend_material(asset_dict, renderer)
            first_rec = result.recommendations[0] if result.recommendations else None
            mat_name   = first_rec.material_name if first_rec else ""
            confidence = first_rec.confidence    if first_rec else 0.0
            self.log_info(f"Material recommendation: {mat_name} (confidence={confidence:.2f}, source={first_rec.source if first_rec else 'none'}).")
            return {
                "recommendation_json": json.dumps(result.to_dict(), sort_keys=True, default=str),
                "material_name":        mat_name,
                "confidence":           confidence,
                "exec_out": True,
            }
        except Exception as exc:
            self.log_error(f"Material recommendation failed: {exc}")
            return {"recommendation_json": "{}", "material_name": "", "confidence": 0.0, "exec_out": True}

def register_node():
    return Hou_Mcp_Material_Recommend
